values
('bmlt-clinpath-mcq-001','BMLT','BMLT NHPC Licensing','mcq','free',1,'{"question":"Routine urinalysis: which specimen is preferred?","translation":"Routine urinalysis मा कुन specimen राम्रो?","options":["First-morning midstream urine","Random saliva","EDTA blood","Stool"],"correctIndex":0,"explanation":"First-morning urine is concentrated; midstream collection helps reduce contamination.","explanationNe":"यो finding सम्बन्धित परीक्षणको interpretation मा उपयोगी हुन्छ। नमुनाको गुणस्तर, clinical अवस्था र laboratory protocol सँगै विचार गर्नुहोस्।","topic":"Clinical Pathology"}'::jsonb,true),
('bmlt-clinpath-mcq-002','BMLT','BMLT NHPC Licensing','mcq','free',2,'{"question":"Which urine finding strongly suggests glomerular bleeding?","translation":"Glomerular bleeding को बलियो संकेत कुन हो?","options":["RBC casts","Squamous cells","Mucus threads","Calcium oxalate only"],"correctIndex":0,"explanation":"RBC casts indicate bleeding from the kidney nephron and are strongly associated with glomerular disease.","explanationNe":"यो finding सम्बन्धित परीक्षणको interpretation मा उपयोगी हुन्छ। नमुनाको गुणस्तर, clinical अवस्था र laboratory protocol सँगै विचार गर्नुहोस्।","topic":"Clinical Pathology"}'::jsonb,true),
('bmlt-clinpath-mcq-003','BMLT','BMLT NHPC Licensing','mcq','free',3,'{"question":"Urine nitrite positivity commonly indicates:","translation":"Urine nitrite positive हुँदा प्रायः के जनाउँछ?","options":["Nitrate-reducing bacteria","Ketones","Albumin only","Low pH"],"correctIndex":0,"explanation":"Many urinary gram-negative bacteria reduce nitrate to nitrite; a negative result does not exclude UTI.","explanationNe":"यो finding सम्बन्धित परीक्षणको interpretation मा उपयोगी हुन्छ। नमुनाको गुणस्तर, clinical अवस्था र laboratory protocol सँगै विचार गर्नुहोस्।","topic":"Clinical Pathology"}'::jsonb,true),
('bmlt-clinpath-mcq-004','BMLT','BMLT NHPC Licensing','mcq','free',4,'{"question":"Urine strip protein pad is most sensitive to:","translation":"Urine strip protein pad कुनमा बढी sensitive हुन्छ?","options":["Albumin","Globulin equally","Bence Jones protein","Hemoglobin"],"correctIndex":0,"explanation":"The indicator-dye protein-error principle is most sensitive to albumin.","explanationNe":"यो finding सम्बन्धित परीक्षणको interpretation मा उपयोगी हुन्छ। नमुनाको गुणस्तर, clinical अवस्था र laboratory protocol सँगै विचार गर्नुहोस्।","topic":"Clinical Pathology"}'::jsonb,true),
('bmlt-clinpath-mcq-005','BMLT','BMLT NHPC Licensing','mcq','free',5,'{"question":"Envelope-shaped urine crystals are usually:","translation":"Envelope आकारका urine crystals कुन हुन्?","options":["Calcium oxalate dihydrate","Cystine","Uric acid","Ammonium biurate"],"correctIndex":0,"explanation":"Calcium oxalate dihydrate commonly appears as an envelope with an internal X.","explanationNe":"यो finding सम्बन्धित परीक्षणको interpretation मा उपयोगी हुन्छ। नमुनाको गुणस्तर, clinical अवस्था र laboratory protocol सँगै विचार गर्नुहोस्।","topic":"Clinical Pathology"}'::jsonb,true),
('bmlt-clinpath-mcq-006','BMLT','BMLT NHPC Licensing','mcq','free',6,'{"question":"Broad waxy casts are associated with:","translation":"Broad waxy casts कुन अवस्थासँग सम्बन्धित छन्?","options":["Advanced chronic renal disease","Normal hydration only","Cystitis only","Liver disease only"],"correctIndex":0,"explanation":"Broad waxy casts may form in dilated tubules and are associated with advanced chronic kidney disease.","explanationNe":"यो finding सम्बन्धित परीक्षणको interpretation मा उपयोगी हुन्छ। नमुनाको गुणस्तर, clinical अवस्था र laboratory protocol सँगै विचार गर्नुहोस्।","topic":"Clinical Pathology"}'::jsonb,true),
('bmlt-clinpath-mcq-007','BMLT','BMLT NHPC Licensing','mcq','free',7,'{"question":"Urine sediment for microscopy is commonly prepared by:","translation":"Urine microscopy का लागि sediment कसरी तयार गरिन्छ?","options":["Centrifuging a measured volume","Boiling urine","Adding EDTA","Filtering through gauze"],"correctIndex":0,"explanation":"A standardized volume is centrifuged and the sediment is resuspended for examination.","explanationNe":"यो finding सम्बन्धित परीक्षणको interpretation मा उपयोगी हुन्छ। नमुनाको गुणस्तर, clinical अवस्था र laboratory protocol सँगै विचार गर्नुहोस्।","topic":"Clinical Pathology"}'::jsonb,true),
('bmlt-clinpath-mcq-008','BMLT','BMLT NHPC Licensing','mcq','free',8,'{"question":"Fresh stool is especially useful for observing:","translation":"Fresh stool विशेष गरी कुन कुरा हेर्न उपयोगी हुन्छ?","options":["Motile trophozoites","RBC casts","Sperm count","Platelet clumps"],"correctIndex":0,"explanation":"Fresh stool preserves trophozoite motility and morphology; prompt examination matters.","explanationNe":"यो finding सम्बन्धित परीक्षणको interpretation मा उपयोगी हुन्छ। नमुनाको गुणस्तर, clinical अवस्था र laboratory protocol सँगै विचार गर्नुहोस्।","topic":"Clinical Pathology"}'::jsonb,true),
('bmlt-clinpath-mcq-009','BMLT','BMLT NHPC Licensing','mcq','free',9,'{"question":"Stool occult blood specimen collection should follow:","translation":"Stool occult blood नमुना कसरी संकलन गर्ने?","options":["Specific kit instructions","Urine collection instructions","Blood culture protocol","No collection rules"],"correctIndex":0,"explanation":"Guaiac and immunochemical tests have different requirements; avoid contamination and follow kit instructions.","explanationNe":"यो finding सम्बन्धित परीक्षणको interpretation मा उपयोगी हुन्छ। नमुनाको गुणस्तर, clinical अवस्था र laboratory protocol सँगै विचार गर्नुहोस्।","topic":"Clinical Pathology"}'::jsonb,true),
('bmlt-clinpath-mcq-010','BMLT','BMLT NHPC Licensing','mcq','free',10,'{"question":"Steatorrhea commonly produces stool that is:","translation":"Steatorrhea मा stool कस्तो हुन्छ?","options":["Bulky and greasy","Hard small pellets","Always black","Always watery"],"correctIndex":0,"explanation":"Excess fecal fat can cause bulky, pale, greasy and difficult-to-flush stool.","explanationNe":"यो finding सम्बन्धित परीक्षणको interpretation मा उपयोगी हुन्छ। नमुनाको गुणस्तर, clinical अवस्था र laboratory protocol सँगै विचार गर्नुहोस्।","topic":"Clinical Pathology"}'::jsonb,true),
('bmlt-clinpath-mcq-011','BMLT','BMLT NHPC Licensing','mcq','free',11,'{"question":"Typical acute bacterial meningitis CSF shows:","translation":"Acute bacterial meningitis मा CSF सामान्यतः कस्तो हुन्छ?","options":["Neutrophils high, protein high, glucose low","Lymphocytes only, glucose high","No cells","Protein very low"],"correctIndex":0,"explanation":"Bacterial meningitis commonly produces neutrophilic pleocytosis, increased protein and decreased glucose.","explanationNe":"यो finding सम्बन्धित परीक्षणको interpretation मा उपयोगी हुन्छ। नमुनाको गुणस्तर, clinical अवस्था र laboratory protocol सँगै विचार गर्नुहोस्।","topic":"Clinical Pathology"}'::jsonb,true),
('bmlt-clinpath-mcq-012','BMLT','BMLT NHPC Licensing','mcq','free',12,'{"question":"CSF glucose should be compared with:","translation":"CSF glucose कुनसँग तुलना गर्नुपर्छ?","options":["Simultaneous blood glucose","Urine pH","Stool glucose","Old blood glucose"],"correctIndex":0,"explanation":"CSF glucose depends on blood glucose; a paired sample supports interpretation.","explanationNe":"यो finding सम्बन्धित परीक्षणको interpretation मा उपयोगी हुन्छ। नमुनाको गुणस्तर, clinical अवस्था र laboratory protocol सँगै विचार गर्नुहोस्।","topic":"Clinical Pathology"}'::jsonb,true),
('bmlt-clinpath-mcq-013','BMLT','BMLT NHPC Licensing','mcq','free',13,'{"question":"CSF for cell count should be:","translation":"CSF cell count को नमुना कस्तो हुनुपर्छ?","options":["Delivered promptly","Stored open for hours","Frozen immediately","Mixed with formalin"],"correctIndex":0,"explanation":"Cells deteriorate rapidly, so prompt delivery and test-specific handling are essential.","explanationNe":"यो finding सम्बन्धित परीक्षणको interpretation मा उपयोगी हुन्छ। नमुनाको गुणस्तर, clinical अवस्था र laboratory protocol सँगै विचार गर्नुहोस्।","topic":"Clinical Pathology"}'::jsonb,true),
('bmlt-clinpath-mcq-014','BMLT','BMLT NHPC Licensing','mcq','free',14,'{"question":"Suspected gout crystals are examined in:","translation":"Gout शंका हुँदा crystals कुन fluid मा हेर्छन्?","options":["Synovial fluid","Saliva","Sputum","Urine only"],"correctIndex":0,"explanation":"Synovial fluid microscopy can identify monosodium urate crystals.","explanationNe":"यो finding सम्बन्धित परीक्षणको interpretation मा उपयोगी हुन्छ। नमुनाको गुणस्तर, clinical अवस्था र laboratory protocol सँगै विचार गर्नुहोस्।","topic":"Clinical Pathology"}'::jsonb,true),
('bmlt-clinpath-mcq-015','BMLT','BMLT NHPC Licensing','mcq','free',15,'{"question":"Needle-shaped negatively birefringent synovial crystals indicate:","translation":"Needle-shaped negative birefringent synovial crystal कुन हो?","options":["Monosodium urate","Calcium pyrophosphate","Cystine","Cholesterol"],"correctIndex":0,"explanation":"Monosodium urate crystals are needle-shaped and negatively birefringent under polarized light.","explanationNe":"यो finding सम्बन्धित परीक्षणको interpretation मा उपयोगी हुन्छ। नमुनाको गुणस्तर, clinical अवस्था र laboratory protocol सँगै विचार गर्नुहोस्।","topic":"Clinical Pathology"}'::jsonb,true),
('bmlt-clinpath-mcq-016','BMLT','BMLT NHPC Licensing','mcq','free',16,'{"question":"Light''s criteria use pleural fluid and serum:","translation":"Light''s criteria मा pleural fluid र serum को कुन कुरा प्रयोग हुन्छ?","options":["Protein and LDH","Glucose only","Sodium only","Cell morphology only"],"correctIndex":0,"explanation":"Protein and LDH ratios help classify pleural effusions as exudates or transudates.","explanationNe":"यो finding सम्बन्धित परीक्षणको interpretation मा उपयोगी हुन्छ। नमुनाको गुणस्तर, clinical अवस्था र laboratory protocol सँगै विचार गर्नुहोस्।","topic":"Clinical Pathology"}'::jsonb,true),
('bmlt-clinpath-mcq-017','BMLT','BMLT NHPC Licensing','mcq','free',17,'{"question":"A transudative effusion may result from:","translation":"Transudative effusion कुन कारणले हुन सक्छ?","options":["Systemic hydrostatic/oncotic imbalance","Local infection always","Malignant cells always","Crystal deposition"],"correctIndex":0,"explanation":"Heart failure and systemic pressure or oncotic disturbances can cause transudates.","explanationNe":"यो finding सम्बन्धित परीक्षणको interpretation मा उपयोगी हुन्छ। नमुनाको गुणस्तर, clinical अवस्था र laboratory protocol सँगै विचार गर्नुहोस्।","topic":"Clinical Pathology"}'::jsonb,true),
('bmlt-clinpath-mcq-018','BMLT','BMLT NHPC Licensing','mcq','free',18,'{"question":"Sperm concentration can be measured using:","translation":"Sperm concentration कसरी मापन गर्न सकिन्छ?","options":["Validated counting chamber","Widal test","Gram stain","ESR tube"],"correctIndex":0,"explanation":"A validated counting chamber or analyzer method is used to determine sperm concentration.","explanationNe":"यो finding सम्बन्धित परीक्षणको interpretation मा उपयोगी हुन्छ। नमुनाको गुणस्तर, clinical अवस्था र laboratory protocol सँगै विचार गर्नुहोस्।","topic":"Clinical Pathology"}'::jsonb,true),
