('bmlt-clinpath-mcq-020','BMLT','BMLT NHPC Licensing','mcq','free',20,'{"question":"Pregnancy tests detect:","translation":"Pregnancy test ले के detect गर्छ?","options":["hCG","Insulin","TSH","Albumin"],"correctIndex":0,"explanation":"Urine or serum pregnancy tests detect human chorionic gonadotropin.","explanationNe":"यो finding सम्बन्धित परीक्षणको interpretation मा उपयोगी हुन्छ। नमुनाको गुणस्तर, clinical अवस्था र laboratory protocol सँगै विचार गर्नुहोस्।","topic":"Clinical Pathology"}'::jsonb,true),
('bmlt-clinpath-mcq-021','BMLT','BMLT NHPC Licensing','mcq','free',21,'{"question":"Most rapid urine pregnancy tests use:","translation":"धेरै rapid urine pregnancy test को principle के हो?","options":["Lateral-flow immunoassay","Electrophoresis","RBC agglutination","Acid-fast staining"],"correctIndex":0,"explanation":"Antibodies in lateral-flow assays detect hCG.","explanationNe":"यो finding सम्बन्धित परीक्षणको interpretation मा उपयोगी हुन्छ। नमुनाको गुणस्तर, clinical अवस्था र laboratory protocol सँगै विचार गर्नुहोस्।","topic":"Clinical Pathology"}'::jsonb,true),
('bmlt-clinpath-mcq-022','BMLT','BMLT NHPC Licensing','mcq','free',22,'{"question":"Copper reduction urine tests screen for:","translation":"Copper reduction urine test ले के screen गर्छ?","options":["Reducing substances","Specific albumin only","Nitrite","Ketones only"],"correctIndex":0,"explanation":"Copper reduction methods detect several reducing sugars, unlike glucose-specific oxidase strips.","explanationNe":"यो finding सम्बन्धित परीक्षणको interpretation मा उपयोगी हुन्छ। नमुनाको गुणस्तर, clinical अवस्था र laboratory protocol सँगै विचार गर्नुहोस्।","topic":"Clinical Pathology"}'::jsonb,true),
('bmlt-clinpath-mcq-023','BMLT','BMLT NHPC Licensing','mcq','free',23,'{"question":"Bence Jones proteins are free:","translation":"Bence Jones protein के हो?","options":["Monoclonal immunoglobulin light chains","Albumin fragments only","Hemoglobin chains","Fibrinogen"],"correctIndex":0,"explanation":"Free monoclonal light chains may be excreted in plasma-cell disorders such as myeloma.","explanationNe":"यो finding सम्बन्धित परीक्षणको interpretation मा उपयोगी हुन्छ। नमुनाको गुणस्तर, clinical अवस्था र laboratory protocol सँगै विचार गर्नुहोस्।","topic":"Clinical Pathology"}'::jsonb,true),
('bmlt-clinpath-mcq-024','BMLT','BMLT NHPC Licensing','mcq','free',24,'{"question":"Urine specific gravity may be measured by:","translation":"Urine specific gravity कुन विधिबाट मापन गर्न सकिन्छ?","options":["Refractometry","Gram staining","PT assay","Cell count"],"correctIndex":0,"explanation":"A refractometer estimates specific gravity from the refractive index.","explanationNe":"यो finding सम्बन्धित परीक्षणको interpretation मा उपयोगी हुन्छ। नमुनाको गुणस्तर, clinical अवस्था र laboratory protocol सँगै विचार गर्नुहोस्।","topic":"Clinical Pathology"}'::jsonb,true),
('bmlt-clinpath-mcq-025','BMLT','BMLT NHPC Licensing','mcq','free',25,'{"question":"Many squamous epithelial cells in urine suggest:","translation":"Urine मा धेरै squamous epithelial cells हुनु के संकेत हो?","options":["Possible external contamination","Confirmed glomerulonephritis","Normal sterile sample always","Renal casts"],"correctIndex":0,"explanation":"Squamous cells and mixed flora can indicate contamination from external genital surfaces.","explanationNe":"यो finding सम्बन्धित परीक्षणको interpretation मा उपयोगी हुन्छ। नमुनाको गुणस्तर, clinical अवस्था र laboratory protocol सँगै विचार गर्नुहोस्।","topic":"Clinical Pathology"}'::jsonb,true),
('bmlt-clinpath-mock-001','BMLT','BMLT NHPC Licensing','mock','free',1,'{"question":"Urine has bacteria and numerous squamous cells. Best interpretation?","translation":"Urine मा bacteria र धेरै squamous cells छन्। सही interpretation?","options":["Possible contamination; recollect correctly","Confirmed kidney infection","Always normal","Proof of tuberculosis"],"correctIndex":0,"explanation":"Numerous squamous cells raise concern for contamination; recollect if clinically appropriate.","explanationNe":"यो finding सम्बन्धित परीक्षणको interpretation मा उपयोगी हुन्छ। नमुनाको गुणस्तर, clinical अवस्था र laboratory protocol सँगै विचार गर्नुहोस्।","topic":"Clinical Pathology"}'::jsonb,true),
('bmlt-clinpath-mock-002','BMLT','BMLT NHPC Licensing','mock','free',2,'{"question":"Dipstick blood is positive but microscopy has no RBCs. Possible explanation?","translation":"Dipstick blood positive तर microscopy मा RBC छैन। कारण?","options":["Hemoglobin or myoglobin","Albumin only","Bilirubin only","Squamous cells"],"correctIndex":0,"explanation":"The strip detects heme activity and may react to hemoglobin or myoglobin without intact RBCs.","explanationNe":"यो finding सम्बन्धित परीक्षणको interpretation मा उपयोगी हुन्छ। नमुनाको गुणस्तर, clinical अवस्था र laboratory protocol सँगै विचार गर्नुहोस्।","topic":"Clinical Pathology"}'::jsonb,true),
('bmlt-clinpath-mock-003','BMLT','BMLT NHPC Licensing','mock','free',3,'{"question":"Colorless hexagonal urine crystals suggest:","translation":"Colorless hexagonal urine crystals ले के जनाउँछ?","options":["Cystine","Calcium oxalate","Uric acid","Triple phosphate"],"correctIndex":0,"explanation":"Hexagonal cystine crystals are characteristic and may occur in cystinuria.","explanationNe":"यो finding सम्बन्धित परीक्षणको interpretation मा उपयोगी हुन्छ। नमुनाको गुणस्तर, clinical अवस्था र laboratory protocol सँगै विचार गर्नुहोस्।","topic":"Clinical Pathology"}'::jsonb,true),
('bmlt-clinpath-mock-004','BMLT','BMLT NHPC Licensing','mock','free',4,'{"question":"Heavy quantitative proteinuria is most consistent with:","translation":"Quantitative परीक्षणमा धेरै proteinuria कुनसँग मिल्छ?","options":["Nephrotic-range protein loss","Simple contamination only","Nitrite positivity","Low urine pH"],"correctIndex":0,"explanation":"Nephrotic syndrome is associated with heavy proteinuria quantified by timed urine or protein/creatinine ratio.","explanationNe":"यो finding सम्बन्धित परीक्षणको interpretation मा उपयोगी हुन्छ। नमुनाको गुणस्तर, clinical अवस्था र laboratory protocol सँगै विचार गर्नुहोस्।","topic":"Clinical Pathology"}'::jsonb,true),
('bmlt-clinpath-mock-005','BMLT','BMLT NHPC Licensing','mock','free',5,'{"question":"O&P stool is delayed without preservative. Main concern?","translation":"O&P stool preservative बिना ढिलो भयो। मुख्य समस्या?","options":["Trophozoite morphology deteriorates","All eggs disappear instantly","Sample becomes sterile","Occult blood always positive"],"correctIndex":0,"explanation":"Delay may distort fragile trophozoites; examine promptly or use appropriate preservative.","explanationNe":"यो finding सम्बन्धित परीक्षणको interpretation मा उपयोगी हुन्छ। नमुनाको गुणस्तर, clinical अवस्था र laboratory protocol सँगै विचार गर्नुहोस्।","topic":"Clinical Pathology"}'::jsonb,true),
('bmlt-clinpath-mock-006','BMLT','BMLT NHPC Licensing','mock','free',6,'{"question":"Excess fat droplets in stool microscopy suggest:","translation":"Stool microscopy मा धेरै fat droplets ले के जनाउँछ?","options":["Fat malabsorption","Renal tubular injury","Meningitis","Hemolysis"],"correctIndex":0,"explanation":"Excess fecal fat supports steatorrhea and should be correlated with clinical/quantitative testing.","explanationNe":"यो finding सम्बन्धित परीक्षणको interpretation मा उपयोगी हुन्छ। नमुनाको गुणस्तर, clinical अवस्था र laboratory protocol सँगै विचार गर्नुहोस्।","topic":"Clinical Pathology"}'::jsonb,true),
('bmlt-clinpath-mock-007','BMLT','BMLT NHPC Licensing','mock','free',7,'{"question":"Cloudy CSF with neutrophilia and low glucose most suggests:","translation":"Cloudy CSF, neutrophilia र low glucose ले के जनाउँछ?","options":["Bacterial meningitis","Typical viral meningitis","Normal CSF","Non-inflammatory condition"],"correctIndex":0,"explanation":"This pattern is characteristic of bacterial infection and needs urgent clinical correlation.","explanationNe":"यो finding सम्बन्धित परीक्षणको interpretation मा उपयोगी हुन्छ। नमुनाको गुणस्तर, clinical अवस्था र laboratory protocol सँगै विचार गर्नुहोस्।","topic":"Clinical Pathology"}'::jsonb,true),
